export function useSendDraftMutation(
  options?: UseMutationOptions<
    Message,
    Error,
    { id: string; req: SendDraftRequest }
  >
) {
  return useMutation<Message, Error, { id: string; req: SendDraftRequest }>({
    mutationFn: ({ id, req }) => sendDraft(id, req),
    ...options,
  })
}
